-- Biblioteca Inclusiva · Língua Inglesa do 7º ano completa.
WITH lessons(code,title,goal) AS (VALUES
('EF07LI01','Interação oral colaborativa','Participar de trocas com preparação, turnos flexíveis e fala opcional.'),
('EF07LI02','Entrevistas e coleta de informações','Formular perguntas e registrar respostas de personagens ou fontes públicas, sem exposição pessoal.'),
('EF07LI03','Conhecimentos prévios na compreensão oral','Ativar repertório, contexto e previsões antes de escutar.'),
('EF07LI04','Contexto e finalidade de textos orais','Identificar interlocutores, assunto, intenção e situação comunicativa.'),
('EF07LI05','Informações principais em textos orais','Selecionar fatos e acontecimentos relevantes em narrativas e relatos.'),
('EF07LI06','Composição de textos orais','Planejar sequência, palavras-chave e recursos de apoio para comunicação multimodal.'),
('EF07LI07','Leitura rápida para sentido geral','Usar título, início, fim e palavras repetidas para captar assunto.'),
('EF07LI08','Objetivos de leitura','Definir estratégia conforme finalidade, gênero e informação procurada.'),
('EF07LI09','Informações específicas em textos','Localizar detalhes e citar pistas sem tradução palavra por palavra.'),
('EF07LI10','Relações entre parágrafos','Reconhecer continuidade, contraste, causa, consequência e sequência.'),
('EF07LI11','Pesquisa e fontes confiáveis','Avaliar autoria, instituição, data, evidências e finalidade em fontes digitais.'),
('EF07LI12','Planejamento da escrita','Definir público, objetivo, gênero, suporte e recursos antes de produzir.'),
('EF07LI13','Organização em parágrafos','Agrupar ideias e usar títulos, tópicos e conectores para orientar o leitor.'),
('EF07LI14','Produção de textos diversos','Produzir e revisar textos com cenários e personagens fictícios.'),
('EF07LI15','Passado simples e contínuo','Distinguir fatos concluídos e ações em andamento em narrativas.'),
('EF07LI16','Conectores de sequência e causa','Usar before, after, when, while e because para articular acontecimentos.'),
('EF07LI17','Polissemia e contexto','Inferir sentidos de palavras polissêmicas pelo contexto e gênero.'),
('EF07LI18','Pronúncia do passado regular','Reconhecer variantes de pronúncia de -ed sem penalizar sotaque.'),
('EF07LI19','Pronomes sujeito e objeto','Usar pronomes conforme função sintática e referente claro.'),
('EF07LI20','Can e could','Expressar habilidades presentes e passadas em personagens fictícios.'),
('EF07LI21','Inglês como língua global','Analisar circulação mundial do inglês sem tratar uma variedade como superior.'),
('EF07LI22','Variação linguística','Reconhecer sotaques e vocabulários diversos como legítimos e contextuais.'),
('EF07LI23','Língua, identidade e respeito','Combater preconceito linguístico e valorizar repertórios multilíngues.')
), normalized AS (
 SELECT code,'src/escola-brilha/ingles-7ano/bncc-workshops.ts'::text AS source_key,title,goal FROM lessons
)
