SELECT source_key,'audit-2026-09-04',code,title,'fundamental_2','7º Ano','Língua Inglesa',title,goal,ARRAY['tea','tdah','dislexia','deficiencia_intelectual','comunicacao','motora_escrita','sensorial_auditiva','sensorial_visual'],
jsonb_build_array(jsonb_build_object('title','Guia inclusivo de Língua Inglesa — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Entrada acessível e comunicação consentida','content',jsonb_build_array('Antecipe gênero, contexto, finalidade e palavras-chave; ofereça áudio repetível, velocidade e volume reguláveis, legenda, transcrição e pausas.','Fala pública, leitura em voz alta e entrevista entre colegas são opcionais. Use personagem fictício, fonte pública, roteiro escrito, comunicação alternativa, ensaio ou áudio privado.','Avalie compreensão e inteligibilidade, não imitação de sotaque; aceite tempo de processamento e formas multilíngues de construir sentido.')),
 jsonb_build_object('heading','Pesquisa, leitura e escrita','content',jsonb_build_array('Modele previsão, leitura global, busca de detalhes, relações entre parágrafos e verificação de autoria, instituição, data, evidência e finalidade.','Escrita segue público, propósito, ideias, organização, rascunho, revisão e versão final; biografia e entrevista devem usar personagens ou figuras públicas com fontes adequadas.','Ferramentas digitais não exigem perfil público, contato com desconhecidos ou publicação; dados e exemplos devem ser fictícios ou públicos agregados.')),
 jsonb_build_object('heading','Privacidade, identidade e autoria','content',jsonb_build_array('Nunca peça história de vida, memória difícil, foto, nome completo, endereço, geolocalização, rotina, habilidade pessoal, diagnóstico, religião, nacionalidade, etnia ou informação familiar.','Não apresente sotaque, país, inglês nativo ou cultura como superiores; discuta língua e identidade sem exigir autodeclaração.','Use textos e áudios autorizados, licenciados ou em domínio público conforme aplicável; não reproduza letras ou obras integrais protegidas.')),
 jsonb_build_object('heading','Critério','content','Compreende quatro de cinco itens e produz três significados adequados ao contexto, citando evidência e revisando a resposta no modo acessível escolhido.')))),
jsonb_build_array(jsonb_build_object('title','1. Prever e compreender','instruction','Ative repertório, identifique contexto e escolha estratégia antes de ler ou escutar.','activity','Registre assunto, finalidade, duas informações e uma pista sobre '||lower(title)||'.','support','Legenda, transcrição, áudio regulável, texto segmentado, glossário e leitor de tela.'),jsonb_build_object('title','2. Relacionar e praticar','instruction','Conecte forma, significado, função e evidência em exemplos fictícios.','activity','Organize, complete ou transforme três itens e explique uma escolha.','support','Modelo resolvido, cartões, linha do tempo, banco de palavras e pistas graduadas.'),jsonb_build_object('title','3. Produzir e revisar','instruction','Planeje resposta para propósito e público, produza no formato escolhido e revise sentido e forma.','activity','Cite evidência ou explique estratégia sem fala pública obrigatória.','support','Apontamento, comunicação alternativa, fala opcional, áudio privado, digitação, escrita ou tecnologia assistiva.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Identifica contexto, finalidade, informações e pista pertinente.'),jsonb_build_object('page',2,'answer','Relaciona forma e significado e explica escolha com apoio adequado.'),jsonb_build_object('page',3,'answer','Produz e revisa resposta adequada; sotaque e comunicação alternativa não são penalizados.','teacher_note','Registre compreensão, estratégia e apoio eficaz; não registre voz, história pessoal, identidade ou localização.')),
jsonb_build_object('response_modes',jsonb_build_array('pointing','selection','cards','aac','oral_optional','private_rehearsal','private_audio','typing','writing','assistive_technology'),'routine','adjustable','one_instruction_at_a_time',true,'read_aloud',true,'captions',true,'transcript',true,'large_text',true,'segmented_text',true,'visual_schedule',true,'planned_pause',true,'audio_replay',true,'playback_speed_control',true,'volume_control',true,'no_forced_speaking',true,'no_forced_read_aloud',true,'no_peer_interview_required',true,'accent_dignity',true,'multilingual_respect',true,'privacy_preserving',true,'fictional_biography_only',true,'no_live_geolocation',true,'no_personal_account_required',true,'no_contact_with_strangers',true,'no_public_posting',true,'no_life_story_disclosure',true,'no_health_disclosure',true,'no_religion_ethnicity_nationality_collection',true,'source_verification',true,'cultural_respect',true,'copyright_respect',true,'mobility_vision_hearing_inclusive',true,'print','grayscale-safe'),true,true,true,'published','/escola-brilha/ingles-7ano/'||lower(code) FROM normalized
